def my_cad_function(args):
    import cadquery as cq
    import os
    from collections import defaultdict

    input_file = os.path.expanduser(args.get("input_file", ""))
    if not input_file or not os.path.exists(input_file):
        raise ValueError(f"Missing or invalid args['input_file']: {input_file}")

    imported = cq.importers.importStep(input_file)
    root = imported.val() if hasattr(imported, "val") else imported

    # pick biggest solid
    solids = list(cq.Workplane(obj=root).solids().vals()) if not hasattr(root, "Solids") else list(root.Solids())
    if not solids:
        raise ValueError("No solids found in imported STEP")
    main = max(solids, key=lambda s: float(s.Volume()))

    bb = main.BoundingBox()
    xmin, xmax = bb.xmin, bb.xmax
    ymin, ymax = bb.ymin, bb.ymax
    zmin, zmax = bb.zmin, bb.zmax
    xlen, ylen, zlen = bb.xlen, bb.ylen, bb.zlen

    print(f"MAIN BBOX: x[{xmin:.3f},{xmax:.3f}] y[{ymin:.3f},{ymax:.3f}] z[{zmin:.3f},{zmax:.3f}]")

    # OCP tools (avoid TopTools_ListIteratorOfListOfShape which is not available in this environment)
    from OCP.BRepAdaptor import BRepAdaptor_Curve
    from OCP.GeomAbs import GeomAbs_Circle
    from OCP.BRepFilletAPI import BRepFilletAPI_MakeFillet

    # --- heuristics / tolerances ---
    # left head region lives near x-min; keep away from shoulder/pocket by capping around ~100mm
    head_x_limit = xmin + min(110.0, 0.40 * xlen)
    x_edge_cap = xmin + 95.0  # stay on the "big head" side, not into the arm

    tol = max(0.20, 0.004 * max(xlen, ylen, zlen))
    tolY = max(0.50, 0.012 * ylen)

    def near(a, b, t):
        return abs(a - b) <= t

    def edge_center(e: cq.Edge):
        try:
            return e.Center()
        except Exception:
            return e.centerOfMass()

    def in_head_region(e: cq.Edge):
        c = edge_center(e)
        return c.x <= head_x_limit + tol

    def touches_outer_extents(e: cq.Edge):
        eb = e.BoundingBox()
        return (
            near(eb.xmin, xmin, tol) or near(eb.xmax, xmax, tol) or
            near(eb.ymin, ymin, tol) or near(eb.ymax, ymax, tol) or
            near(eb.zmin, zmin, tol) or near(eb.zmax, zmax, tol)
        )

    def near_y_side(e: cq.Edge, yside: float):
        eb = e.BoundingBox()
        return near(eb.ymin, yside, tolY) or near(eb.ymax, yside, tolY)

    def is_line_edge(e: cq.Edge):
        try:
            return e.geomType() == "LINE"
        except Exception:
            return False

    # --- determine which Y side is missing radii by counting "sharp" (line) outer edges in head region ---
    def sharp_line_count_on_y(yside: float):
        cnt = 0
        for e in main.Edges():
            if not in_head_region(e):
                continue
            if not near_y_side(e, yside):
                continue
            if not touches_outer_extents(e):
                continue
            c = edge_center(e)
            if c.x > x_edge_cap + tol:
                continue
            if is_line_edge(e):
                cnt += 1
        return cnt

    cnt_ymin = sharp_line_count_on_y(ymin)
    cnt_ymax = sharp_line_count_on_y(ymax)

    bad_side = ymax if cnt_ymax > cnt_ymin else ymin
    good_side = ymin if bad_side == ymax else ymax

    print(f"Sharp LINE edge count near y={ymin:.3f}: {cnt_ymin}")
    print(f"Sharp LINE edge count near y={ymax:.3f}: {cnt_ymax}")
    print(f"Assuming missing-radii side is y={bad_side:.3f} (reference/good side y={good_side:.3f})")

    # --- detect reference radius from existing circular edges on the good side in the head region ---
    # default from planning stage
    r_ref = 30.0
    bins = defaultdict(float)  # radius_bin -> accumulated edge length (weight)

    for e in main.Edges():
        try:
            if not in_head_region(e):
                continue
            if not near_y_side(e, good_side):
                continue
            if not touches_outer_extents(e):
                continue
            c = edge_center(e)
            if c.x > x_edge_cap + tol:
                continue

            ad = BRepAdaptor_Curve(e.wrapped)
            if ad.GetType() != GeomAbs_Circle:
                continue
            r = float(ad.Circle().Radius())
            if r < 5.0 or r > 100.0:
                continue

            L = float(e.Length())
            b = round(r * 2.0) / 2.0  # 0.5mm bins
            bins[b] += L
        except Exception:
            continue

    if bins:
        # prefer larger radii (head rounds) but still choose the most "dominant" by length
        candidates = [(rb, w) for rb, w in bins.items() if rb >= 10.0]
        if candidates:
            candidates.sort(key=lambda t: t[1], reverse=True)
            r_ref = float(candidates[0][0])

    print(f"Using reference fillet radius r_ref={r_ref:.3f}")

    # --- select edges to fillet: sharp line edges on bad side, head region, outer extents ---
    edges_to_fillet = []
    for e in main.Edges():
        if not in_head_region(e):
            continue
        if not near_y_side(e, bad_side):
            continue
        if not touches_outer_extents(e):
            continue
        c = edge_center(e)
        if c.x > x_edge_cap + tol:
            continue
        if not is_line_edge(e):
            continue
        edges_to_fillet.append(e)

    print(f"Selected edges to fillet on missing side: {len(edges_to_fillet)}")

    # --- apply fillet using OCC (bulk then per-edge fallback) ---
    result_shape = main.wrapped

    def try_fillet(shape_wrapped, edge_list, rad):
        mk = BRepFilletAPI_MakeFillet(shape_wrapped)
        for ee in edge_list:
            mk.Add(rad, ee.wrapped)
        mk.Build()
        if not mk.IsDone():
            return None
        return mk.Shape()

    if edges_to_fillet:
        out = try_fillet(result_shape, edges_to_fillet, r_ref)
        if out is None:
            print("Bulk fillet failed; trying per-edge fillets...")
            applied = 0
            kept = 0
            for ee in edges_to_fillet:
                kept += 1
                mk = BRepFilletAPI_MakeFillet(result_shape)
                mk.Add(r_ref, ee.wrapped)
                mk.Build()
                if mk.IsDone():
                    result_shape = mk.Shape()
                    applied += 1
            print(f"Per-edge fillet applied on {applied}/{kept} edges.")
        else:
            result_shape = out
            print("Bulk fillet applied successfully.")
    else:
        print("No candidate sharp edges found to fillet (nothing changed).")

    result = cq.Shape.cast(result_shape)
    bb2 = result.BoundingBox()
    print(f"FINAL BBOX: x[{bb2.xmin:.3f},{bb2.xmax:.3f}] y[{bb2.ymin:.3f},{bb2.ymax:.3f}] z[{bb2.zmin:.3f},{bb2.zmax:.3f}]")

    return cq.Workplane(obj=result)
